CREATE TABLE "public"."notification_jobs" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."notification_jobs_id_seq" START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 NO CYCLE) NOT NULL,
  "notification_id" uuid,
  "event_id" bigint,
  "job_type" text NOT NULL,
  "run_at" timestamp with time zone NOT NULL,
  "job_status" text DEFAULT 'Pending'::text NOT NULL,
  "attempt_count" integer DEFAULT 0 NOT NULL,
  "maximum_attempts" integer DEFAULT 5 NOT NULL,
  "locked_at" timestamp with time zone,
  "locked_by" text,
  "started_at" timestamp with time zone,
  "completed_at" timestamp with time zone,
  "failed_at" timestamp with time zone,
  "last_error" text,
  "job_payload" jsonb DEFAULT '{}'::jsonb NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL
) USING "heap";
ALTER TABLE "public"."notification_jobs" OWNER TO "postgres";
COMMENT ON TABLE "public"."notification_jobs" IS 'Server-side notification scheduling, retry, delivery and escalation work queue.';
COMMENT ON COLUMN "public"."notification_jobs"."notification_id" IS 'Notification processed by this job, when applicable.';
COMMENT ON COLUMN "public"."notification_jobs"."event_id" IS 'Business event processed by this job, when applicable.';
COMMENT ON COLUMN "public"."notification_jobs"."job_type" IS 'Job operation such as ProcessEvent, DeliverNotification, RepeatNotification, EscalateNotification or ExpireNotification.';
COMMENT ON COLUMN "public"."notification_jobs"."run_at" IS 'UTC timestamp when this job becomes eligible for processing.';
COMMENT ON COLUMN "public"."notification_jobs"."locked_by" IS 'Identifier of the server processor that acquired the job lock.';
COMMENT ON COLUMN "public"."notification_jobs"."job_payload" IS 'Structured non-secret processing context for this job.';
